                                      className="flex-1 px-4 py-2 bg-gradient-to-r from-red-500 to-pink-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                                      onClick={() =>
                                        handleDeleteReport(report.id)
                                      }
                                    >
                                      <span className="material-icons text-sm">
                                        delete
                                      </span>
                                      Delete
                                    </button>
                                  </div>
                                </div>
                              </div>
                            ))
                          ) : (
                            <div className="col-span-full text-center py-12">
                              <span className="material-icons text-6xl text-gray-300 mb-4">
                                search
                              </span>
                              <p className="text-gray-500 text-lg">
                                No rescue pet reports yet
                              </p>
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </div>

                  {user?.role === "admin" && adminMetrics && (
                    <div className="admin-metrics">
                      <h3>Admin Dashboard Metrics</h3>
                      <ul>
                        <li>
                          Total Pets Reported:{" "}
                          {adminMetrics.total_pets_reported}
                        </li>
                        <li>
                          Total Adoptions Approved:{" "}
                          {adminMetrics.total_adoptions_approved}
                        </li>
                        <li>Total Lost: {adminMetrics.total_lost}</li>
                        <li>Total Found: {adminMetrics.total_found}</li>
                        <li>
                          Total Registered Users:{" "}
                          {adminMetrics.total_registered_users}
                        </li>
                        <li>
                          Total Cases Resolved:{" "}
                          {adminMetrics.total_cases_resolved}
                        </li>
                      </ul>
                      {metricsMsg && <div>{metricsMsg}</div>}
                    </div>
                  )}

                  {/* Section 3: MY ADOPTION POSTS */}
                  <div className="bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-lg border border-blue-100 dark:border-slate-600 overflow-hidden">
                    <button
                      onClick={() =>
                        setExpandedSection(
                          expandedSection === "adoptionPosts"
                            ? null
                            : "adoptionPosts"
                        )
                      }
                      className="w-full flex items-center justify-between p-6 hover:bg-blue-50 dark:hover:bg-slate-700 transition-colors"
                    >
                      <div className="flex items-center gap-3">
                        <span className="material-icons text-accent-yellow text-3xl">
                          volunteer_activism
                        </span>
                        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">
                          MY ADOPTION POSTS ({myAdoptionPosts.length})
                        </h2>
                      </div>
                      <span
                        className={`material-icons text-3xl text-accent-yellow transition-transform ${
                          expandedSection === "adoptionPosts"
                            ? "rotate-180"
                            : ""
                        }`}
                      >
                        expand_more
                      </span>
                    </button>

                    {expandedSection === "adoptionPosts" && (
                      <div className="p-6 pt-0">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                          {myAdoptionPosts.length > 0 ? (
                            myAdoptionPosts.map((post) => (
                              <div
                                key={post.id}
                                className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-800 dark:to-blue-900 rounded-2xl shadow-lg overflow-hidden hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-blue-200 dark:border-blue-700"
                              >
                                <div className="relative h-56 overflow-hidden">
                                  <img
                                    src={getImageUrl(post.image)}
                                    alt={post.name}
                                    className="w-full h-full object-cover"
                                    onError={(e) => {
                                      e.target.src = "/default-pet.png";
                                    }}
                                  />
                                  <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                                    <h3 className="text-white font-bold text-lg">
                                      {post.name}
                                    </h3>
                                  </div>
                                </div>
                                <div className="p-5 space-y-3">
                                  <div className="inline-block px-3 py-1 bg-yellow-100 text-accent-yellow rounded-full text-sm font-semibold">
                                    {post.type}
                                  </div>
                                  <div className="space-y-2">
                                    {post.breed && (
                                      <span className="block text-gray-700 dark:text-white text-sm">
                                        <span className="font-semibold">
                                          Breed:
                                        </span>{" "}
                                        {post.breed}
                                      </span>
                                    )}
                                    <span className="block text-gray-700 dark:text-white text-sm">
                                      <span className="font-semibold">
                                        Age:
                                      </span>{" "}
                                      🎂 {post.age} years
                                    </span>
                                    <span className="block text-gray-700 dark:text-white text-sm">
                                      <span className="font-semibold">
                                        Gender:
                                      </span>{" "}
                                      {post.gender === "Male" ? "♂️" : "♀️"}{" "}
                                      {post.gender}
                                    </span>
                                    {post.location && (
                                      <span className="flex items-center gap-1 text-gray-700 dark:text-white text-sm">
                                        <span className="material-icons text-xs">
                                          location_on
                                        </span>
                                        {post.location}
                                      </span>
                                    )}
                                  </div>
                                  <p className="text-gray-600 dark:text-white text-sm leading-relaxed">
                                    {post.description
                                      ? post.description.length > 100
                                        ? `${post.description.substring(
                                            0,
                                            100
                                          )}...`
                                        : post.description
                                      : "No description available"}
                                  </p>
                                  <div className="flex flex-wrap gap-2">
                                    {post.is_vaccinated && (
                                      <span className="px-2 py-1 bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100 rounded-full text-xs font-semibold">
                                        ✓ Vaccinated
                                      </span>
                                    )}
                                    {post.is_diseased && (
                                      <span className="px-2 py-1 bg-orange-100 text-orange-700 rounded-full text-xs font-semibold">
                                        ⚠ Health Condition
                                      </span>
                                    )}
                                  </div>
                                  <div
                                    className={`px-3 py-2 rounded-lg text-center font-semibold text-sm ${
                                      post.report_status === "accepted"
                                        ? "bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100"
                                        : post.report_status === "pending"
                                        ? "bg-yellow-100 text-yellow-700 dark:bg-yellow-800 dark:text-yellow-100"
                                        : "bg-red-100 text-red-700 dark:bg-red-800 dark:text-red-100"
                                    }`}
                                  >
                                    {post.report_status === "pending" &&
                                      "⏳ PENDING REVIEW"}
                                    {post.report_status === "accepted" &&
                                      "✅ APPROVED"}
                                    {post.report_status === "rejected" &&
                                      "❌ REJECTED"}
                                  </div>
                                  {post.admin_comment && (
                                    <div className="bg-gray-50 p-3 rounded-lg text-sm">
                                      <strong className="text-gray-700 dark:text-white">
                                        Admin:
                                      </strong>
                                      <p className="text-gray-600 dark:text-white mt-1">
                                        {post.admin_comment}
                                      </p>
                                    </div>
                                  )}
                                  <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                                    <span className="text-xs text-gray-500 dark:text-slate-300">
                                      Posted:{" "}
                                      {new Date(
                                        post.created_at
                                      ).toLocaleDateString()}
                                    </span>
                                  </div>

                                  {/* View Details Button */}
                                  <button
                                    className="w-full px-4 py-2 bg-gradient-to-r from-yellow-500 to-orange-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2 mt-2"
                                    onClick={() => {
                                      if (post.pet_id) {
                                        fetchPetDetails(post.pet_id);
                                      } else {
                                        setError(
                                          "Pet ID not available for this post"
                                        );
                                        setTimeout(() => setError(""), 3000);
                                      }
                                    }}
                                  >
                                    <span className="material-icons text-sm">
                                      visibility
                                    </span>
                                    View Details
                                  </button>

                                  {/* Delete Button for Adoption Posts */}
                                  <button
                                    className="w-full px-4 py-2 bg-gradient-to-r from-red-500 to-pink-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2 mt-2"
                                    onClick={() => handleDeleteReport(post.id)}
                                  >
                                    <span className="material-icons text-sm">
                                      delete
                                    </span>
                                    Delete Post
                                  </button>
                                </div>
                              </div>
                            ))
                          ) : (
                            <div className="col-span-full text-center py-12">
                              <span className="material-icons text-6xl text-gray-300 mb-4">
                                volunteer_activism
                              </span>
                              <p className="text-gray-500 text-lg">
                                You haven't posted any pets for adoption yet
                              </p>
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ))}

            {activeTab === "report-lost" && (
              <div className="bg-gradient-to-br from-white to-purple-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                <div className="flex items-center gap-3 mb-6 pb-3 border-b-2 border-primary-blue">
                  <span className="material-icons text-primary-blue text-3xl">
                    report
                  </span>
                  <h2 className="text-2xl font-bold text-gray-800 dark:text-white">
                    REPORT LOST PET
                  </h2>
                </div>
                <form onSubmit={handleSubmitPetReport} className="space-y-6">
                  <input type="hidden" name="pet_status" value="lost" />

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Pet Name *
                      </label>
                      <input
                        type="text"
                        name="pet_name"
                        value={petForm.pet_name}
                        onChange={handleFormChange}
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter pet name"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Pet Type *
                      </label>
                      <select
                        name="pet_type"
                        value={petForm.pet_type}
                        onChange={handleFormChange}
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors bg-slate-50/50"
                      >
                        <option value="Dog">Dog</option>
                        <option value="Cat">Cat</option>
                        <option value="Bird">Bird</option>
                        <option value="Other">Other</option>
                      </select>
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Breed
                      </label>
                      <input
                        type="text"
                        name="pet_breed"
                        value={petForm.pet_breed}
                        onChange={handleFormChange}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter breed"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Age
                      </label>
                      <input
                        type="number"
                        name="pet_age"
                        value={petForm.pet_age}
                        onChange={handleFormChange}
                        min="0"
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter age"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Color
                      </label>
                      <input
                        type="text"
                        name="pet_colour"
                        value={petForm.pet_colour}
                        onChange={handleFormChange}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter color"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Weight (kg)
                      </label>
                      <input
                        type="number"
                        name="pet_weight"
                        value={petForm.pet_weight}
                        onChange={handleFormChange}
                        step="0.1"
                        min="0"
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter weight"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Gender
                      </label>
                      <select
                        name="pet_gender"
                        value={petForm.pet_gender}
                        onChange={handleFormChange}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors bg-slate-50/50"
                      >
                        <option value="Male">Male</option>
                        <option value="Female">Female</option>
                        <option value="Unknown">Unknown</option>
                      </select>
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Last Seen Location *
                      </label>
                      <input
                        type="text"
                        name="pet_location"
                        value={petForm.pet_location}
                        onChange={handleFormChange}
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter location"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        State
                      </label>
                      <input
                        type="text"
                        name="pet_state"
                        value={petForm.pet_state}
                        onChange={handleFormChange}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter state"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        City
                      </label>
                      <input
                        type="text"
                        name="pet_city"
                        value={petForm.pet_city}
                        onChange={handleFormChange}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter city"
                      />
                    </div>

                    <div className="flex flex-col md:col-span-2">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Pet Photo
                      </label>
                      <input
                        type="file"
                        name="pet_image"
                        accept="image/*"
                        onChange={(e) => {
                          const file = e.target.files[0];
                          setPetForm((prev) => ({
                            ...prev,
                            pet_image: file,
                          }));
                        }}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                      />
                      <p className="text-xs text-gray-500 dark:text-slate-300 mt-2">
                        Choose a clear photo of your pet (JPG, PNG, WebP)
                      </p>
                      {petForm.pet_image && (
                        <div className="mt-4 relative inline-block">
                          <img
                            src={URL.createObjectURL(petForm.pet_image)}
                            alt="Pet preview"
                            className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200"
                          />
                          <button
                            type="button"
                            className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center hover:bg-red-600 transition-colors"
                            onClick={() =>
                              setPetForm((prev) => ({
                                ...prev,
                                pet_image: null,
                              }))
                            }
                          >
                            ×
                          </button>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-col">
                    <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                      Description
                    </label>
                    <textarea
                      name="description"
                      value={petForm.description}
                      onChange={handleFormChange}
                      rows="4"
                      className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors resize-none"
                      placeholder="Describe your pet's appearance, behavior, any distinctive marks..."
                    />
                  </div>

                  <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4 flex items-center gap-2">
                    <span className="text-2xl">💊</span>
                    Medical Information
                  </h3>
                  <div className="space-y-4">
                    <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-slate-700 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-600 transition-colors">
                      <input
                        type="checkbox"
                        name="is_vaccinated"
                        checked={petForm.is_vaccinated}
                        onChange={handleFormChange}
                        className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                      />
                      <label className="text-sm font-medium text-gray-700 dark:text-white cursor-pointer select-none">
                        Is Vaccinated
                      </label>
                    </div>

                    {petForm.is_vaccinated && (
                      <div className="flex flex-col ml-8 animate-fadeIn">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Vaccination Details
                        </label>
                        <input
                          type="text"
                          name="vaccination_details"
                          value={petForm.vaccination_details}
                          onChange={handleFormChange}
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter vaccination details (e.g., Rabies, Distemper, etc.)..."
                        />
                      </div>
                    )}

                    <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-slate-700 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-600 transition-colors">
                      <input
                        type="checkbox"
                        name="is_diseased"
                        checked={petForm.is_diseased}
                        onChange={handleFormChange}
                        className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                      />
                      <label className="text-sm font-medium text-gray-700 dark:text-white cursor-pointer select-none">
                        Is Diseased
                      </label>
                    </div>

                    {petForm.is_diseased && (
                      <div className="flex flex-col ml-8 animate-fadeIn">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Health Conditions
                        </label>
                        <input
                          type="text"
                          name="health_conditions"
                          value={petForm.health_conditions}
                          onChange={handleFormChange}
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Describe health conditions..."
                        />
                      </div>
                    )}
                  </div>

                  <div className="flex flex-col-reverse sm:flex-row gap-4 mt-8 pt-6 border-t-2 border-gray-100">
                    <button
                      type="button"
                      onClick={() => setActiveTab("dashboard")}
                      className="flex-1 px-6 py-3 border-2 border-gray-300 text-gray-700 dark:text-white font-semibold rounded-xl hover:bg-gray-50 hover:border-gray-400 transition-all duration-200"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={submitLoading}
                      className="flex-1 px-6 py-3 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 disabled:hover:shadow-none"
                    >
                      {submitLoading ? (
                        <span className="flex items-center justify-center gap-2">
                          <svg
                            className="animate-spin h-5 w-5"
                            viewBox="0 0 24 24"
                          >
                            <circle
                              className="opacity-25"
                              cx="12"
                              cy="12"
                              r="10"
                              stroke="currentColor"
                              strokeWidth="4"
                              fill="none"
                            />
                            <path
                              className="opacity-75"
                              fill="currentColor"
                              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                            />
                          </svg>
                          Submitting...
                        </span>
                      ) : (
                        "Report Lost Pet"
                      )}
                    </button>
                  </div>
                </form>
              </div>
            )}

            {activeTab === "report-found" && (
              <div className="bg-gradient-to-br from-white to-purple-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                  <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    👁️
                  </span>
                  <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    REPORT FOUND PET
                  </span>
                </h2>
                <form
                  onSubmit={(e) => {
                    e.preventDefault();
                    setSubmitLoading(true);
                    setError("");
                    setSuccessMessage("");

                    const foundFormData = { ...petForm, pet_status: "found" };

                    petsAPI
                      .submitPetRequest(foundFormData)
                      .then((response) => {
                        if (response.data.success) {
                          setSuccessMessage(
                            "Found pet report submitted successfully!"
                          );
                          setPetForm({
                            pet_name: "",
                            pet_type: "Dog",
                            pet_breed: "",
                            pet_age: "",
                            pet_colour: "",
                            pet_weight: "",
                            pet_gender: "Male",
                            pet_location: "",
                            pet_state: "",
                            pet_city: "",
                            pet_status: "found",
                            description: "",
                            is_vaccinated: false,
                            is_diseased: false,
                            vaccination_details: "",
                            health_conditions: "",
                          });
                          loadData();
                          setTimeout(() => setActiveTab("dashboard"), 2000);
                        }
                      })
                      .catch((err) => {
                        setError(
                          err.response?.data?.error ||
                            "Failed to submit found pet report. Please try again."
                        );
                      })
                      .finally(() => setSubmitLoading(false));
                  }}
                >
                  {/* Pet Information */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Pet Name (if known)
                      </label>
                      <input
                        type="text"
                        name="pet_name"
                        value={petForm.pet_name}
                        onChange={handleFormChange}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter pet name"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Pet Type *
                      </label>
                      <select
                        name="pet_type"
                        value={petForm.pet_type}
                        onChange={handleFormChange}
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors bg-slate-50/50"
                      >
                        <option value="Dog">Dog</option>
                        <option value="Cat">Cat</option>
                        <option value="Bird">Bird</option>
                        <option value="Other">Other</option>
                      </select>
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Breed (if known)
                      </label>
                      <input
                        type="text"
                        name="pet_breed"
                        value={petForm.pet_breed}
                        onChange={handleFormChange}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter breed"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Found Location *
                      </label>
                      <input
                        type="text"
                        name="pet_location"
                        value={petForm.pet_location}
                        onChange={handleFormChange}
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Where did you find this pet?"
                      />
                    </div>

                    <div className="flex flex-col md:col-span-2">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Pet Photo
                      </label>
                      <input
                        type="file"
                        name="pet_image"
                        accept="image/*"
                        onChange={(e) => {
                          const file = e.target.files[0];
                          setPetForm((prev) => ({
                            ...prev,
                            pet_image: file,
                          }));
                        }}
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                      />
                      <p className="text-xs text-gray-500 dark:text-slate-300 mt-2">
                        Upload a photo of the found pet
                      </p>
                      {petForm.pet_image && (
                        <div className="mt-4 relative inline-block">
                          <img
                            src={URL.createObjectURL(petForm.pet_image)}
                            alt="Pet preview"
                            className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200"
                          />
                          <button
                            type="button"
                            className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center hover:bg-red-600 transition-colors"
                            onClick={() =>
                              setPetForm((prev) => ({
                                ...prev,
                                pet_image: null,
                              }))
                            }
                          >
                            ×
                          </button>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-col mb-6">
                    <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                      Description *
                    </label>
                    <textarea
                      name="description"
                      value={petForm.description}
                      onChange={handleFormChange}
                      rows="4"
                      required
                      className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors resize-none"
                      placeholder="Describe the found pet's appearance, condition, behavior..."
                    />
                  </div>

                  <div className="flex flex-col-reverse sm:flex-row gap-4 mt-8 pt-6 border-t-2 border-gray-100">
                    <button
                      type="button"
                      onClick={() => setActiveTab("dashboard")}
                      className="flex-1 px-6 py-3 border-2 border-gray-300 text-gray-700 dark:text-white font-semibold rounded-xl hover:bg-gray-50 hover:border-gray-400 transition-all duration-200"
                    >
                      Cancel Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={submitLoading}
                      className="flex-1 px-6 py-3 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 disabled:hover:shadow-none"
                    >
                      {submitLoading ? (
                        <span className="flex items-center justify-center gap-2">
                          <svg
                            className="animate-spin h-5 w-5"
                            viewBox="0 0 24 24"
                          >
                            <circle
                              className="opacity-25"
                              cx="12"
                              cy="12"
                              r="10"
                              stroke="currentColor"
                              strokeWidth="4"
                              fill="none"
                            />
                            <path
                              className="opacity-75"
                              fill="currentColor"
                              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                            />
                          </svg>
                          Submitting...
                        </span>
                      ) : (
                        "Report Found Pet"
                      )}
                    </button>
                  </div>
                </form>
              </div>
            )}

            {activeTab === "notifications" && (
              <div className="bg-gradient-to-br from-white to-purple-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                  <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    🔔
                  </span>
                  <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    NOTIFICATIONS
                  </span>
                </h2>
                <div className="space-y-3">
                  {notifications.length === 0 ? (
                    <div className="text-center py-12">
                      <div className="text-6xl mb-4">🔕</div>
                      <p className="text-gray-500 text-lg">
                        No notifications yet
                      </p>
                    </div>
                  ) : (
                    notifications.map((notification) => (
                      <div
                        key={notification.id}
                        className={`p-4 rounded-xl border-l-4 transition-all duration-200 hover:shadow-md cursor-pointer ${
                          notification.is_read
                            ? "bg-gray-50 border-gray-300"
                            : "bg-blue-50 border-primary-blue shadow-sm"
                        }`}
                        onClick={() => handleNotificationClick(notification)}
                      >
                        <div className="flex items-start justify-between gap-4">
                          <div className="flex-1">
                            <p
                              className={`text-sm ${
                                notification.is_read
                                  ? "text-gray-600 dark:text-white"
                                  : "text-gray-800 dark:text-white font-bold"
                              }`}
                            >
                              {notification.message}
                            </p>
                          </div>
                          <div className="text-xs text-gray-500 dark:text-slate-300 whitespace-nowrap">
                            {new Date(
                              notification.created_at
                            ).toLocaleDateString()}
                          </div>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            )}

            {activeTab === "all-lost" && (
              <div className="bg-gradient-to-br from-white to-purple-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                  <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    🔍
                  </span>
                  <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    ALL APPROVED LOST PETS (
                    {
                      allLostReports.filter(
                        (r) =>
                          r.report_type === "LOST" &&
                          r.report_status === "ACCEPTED"
                      ).length
                    }
                    )
                  </span>
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {loading ? (
                    <div className="col-span-full flex flex-col items-center justify-center py-12">
                      <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-primary-blue mb-4"></div>
                      <p className="text-gray-600 dark:text-white">
                        Loading approved lost pet reports...
                      </p>
                    </div>
                  ) : allLostReports.filter(
                      (r) =>
                        r.report_type === "LOST" &&
                        r.report_status === "ACCEPTED"
                    ).length > 0 ? (
                    allLostReports
                      .filter(
                        (r) =>
                          r.report_type === "LOST" &&
                          r.report_status === "ACCEPTED"
                      )
                      .map((report) => (
                        <div
                          key={report.id}
                          className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 overflow-hidden border border-blue-100"
                        >
                          <div className="relative h-56 overflow-hidden bg-gradient-to-br from-gray-100 to-gray-200">
                            <img
                              src={getImageUrl(report.photo)}
                              alt={report.pet_name}
                              onError={(e) => {
                                e.target.src = "/default-pet.png";
                              }}
                              className="w-full h-full object-cover"
                            />
                            <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                              <h3 className="text-white text-xl font-bold">
                                {report.pet_name}
                              </h3>
                            </div>
                          </div>
                          <div className="p-5 space-y-3">
                            <div className="inline-block px-3 py-1 bg-gradient-to-r from-primary-blue to-primary-teal text-white text-sm font-semibold rounded-full">
                              {report.animal_type}
                            </div>
                            <div className="space-y-2">
                              {report.pet_breed && (
                                <p className="text-sm text-gray-600 dark:text-slate-200">
                                  <span className="font-semibold">Breed:</span>{" "}
                                  {report.pet_breed}
                                </p>
                              )}
                              {report.pet_location && (
                                <p className="text-sm text-gray-600 dark:text-slate-200 flex items-center gap-1">
                                  <span>📍</span>
                                  <span className="font-semibold">
                                    Last Seen:
                                  </span>{" "}
                                  {report.pet_location}
                                </p>
                              )}
                            </div>
                            <p className="text-sm text-gray-700 dark:text-white line-clamp-3">
                              {report.description
                                ? report.description.length > 80
                                  ? `${report.description.substring(0, 80)}...`
                                  : report.description
                                : "No description available"}
                            </p>
                            <div className="flex items-center justify-between pt-3 border-t border-gray-200">
                              <span className="text-xs text-gray-500 dark:text-slate-300">
                                {new Date(
                                  report.created_at
                                ).toLocaleDateString()}
                              </span>
                              <span className="text-xs text-gray-500 dark:text-slate-300">
                                By: {report.owner_username || "Anonymous"}
                              </span>
                            </div>
                            <div className="inline-block px-3 py-1.5 bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100 text-xs font-bold rounded-lg">
                              ✓ APPROVED - LOST
                            </div>
                            <div className="mt-3 p-3 bg-blue-50 rounded-xl flex items-center gap-2 text-sm text-primary-blue font-medium">
                              <span className="text-xl">📞</span>
                              <span>Contact owner to help reunite</span>
                            </div>
                            {report.pet_id && (
                              <button
                                onClick={() => fetchPetDetails(report.pet_id)}
                                className="mt-3 w-full px-4 py-3 bg-gradient-to-r from-blue-500 via-blue-600 to-blue-700 text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 flex items-center justify-center gap-2"
                              >
                                <span className="text-lg">👁️</span>
                                View Full Details
                              </button>
                            )}
                          </div>
                        </div>
                      ))
                  ) : (
                    <div className="col-span-full text-center py-16">
                      <div className="text-6xl mb-4">🔍</div>
                      <p className="text-gray-500 text-lg">
                        No approved lost pet reports from community members yet
                      </p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === "explore-adoption" && (
              <div className="bg-gradient-to-br from-white to-purple-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                  <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    ❤️
                  </span>
                  <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    EXPLORE PETS AVAILABLE FOR ADOPTION (
                    {availableAdoptionPets.length})
                  </span>
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {loading ? (
                    <div className="col-span-full flex flex-col items-center justify-center py-12">
                      <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-primary-blue mb-4"></div>
                      <p className="text-gray-600 dark:text-white">Loading available pets...</p>
                    </div>
                  ) : availableAdoptionPets.length > 0 ? (
                    availableAdoptionPets.map((pet) => (
                      <div
                        key={pet.id}
                        className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 overflow-hidden border border-blue-100"
                      >
                        <div className="relative h-56 overflow-hidden bg-gradient-to-br from-pink-100 to-purple-100">
                          <img
                            src={getImageUrl(pet.image)}
                            alt={pet.name}
                            onError={(e) => {
                              e.target.src = "/default-pet.png";
                            }}
                            className="w-full h-full object-cover"
                          />
                          <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                            <h3 className="text-white text-xl font-bold">
                              {pet.name}
                            </h3>
                          </div>
                        </div>
                        <div className="p-5 space-y-3">
                          <div className="inline-block px-3 py-1 bg-gradient-to-r from-primary-blue to-primary-teal text-white text-sm font-semibold rounded-full">
                            {pet.type}
                          </div>
                          <div className="flex flex-wrap gap-2 text-sm text-gray-600 dark:text-slate-200">
                            {pet.breed && (
                              <span className="px-2 py-1 bg-gray-100 rounded-lg">
                                {pet.breed}
                              </span>
                            )}
                            <span className="px-2 py-1 bg-gray-100 rounded-lg flex items-center gap-1">
                              🎂 {pet.age} years
                            </span>
                            <span className="px-2 py-1 bg-gray-100 rounded-lg">
                              {pet.gender === "Male" ? "♂️" : "♀️"} {pet.gender}
                            </span>
                            {pet.location && (
                              <span className="px-2 py-1 bg-gray-100 rounded-lg flex items-center gap-1">
                                📍 {pet.location}
                              </span>
                            )}
                          </div>
                          <p className="text-sm text-gray-700 dark:text-white line-clamp-3">
                            {pet.description
                              ? pet.description.length > 100
                                ? `${pet.description.substring(0, 100)}...`
                                : pet.description
                              : "No description available"}
                          </p>
                          <div className="flex flex-wrap gap-2">
                            {pet.is_vaccinated && (
                              <span className="px-2 py-1 bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100 text-xs font-semibold rounded-lg flex items-center gap-1">
                                ✓ Vaccinated
                              </span>
                            )}
                            {pet.is_diseased && (
                              <span className="px-2 py-1 bg-yellow-100 text-yellow-700 dark:bg-yellow-800 dark:text-yellow-100 text-xs font-semibold rounded-lg flex items-center gap-1">
                                ⚠ Health Condition
                              </span>
                            )}
                          </div>
                          <div className="inline-block w-full px-3 py-1.5 bg-purple-100 text-purple-700 text-xs font-bold rounded-lg text-center">
                            AVAILABLE FOR ADOPTION
                          </div>
                          <div className="pt-2">
                            {pet.has_pending_request ? (
                              <button
                                className="w-full px-4 py-3 bg-gray-300 text-gray-600 dark:text-slate-200 font-semibold rounded-xl cursor-not-allowed flex items-center justify-center gap-2"
                                disabled
                              >
                                <span className="text-lg">⏳</span>
                                Request Pending
                              </button>
                            ) : (
                              <button
                                onClick={async () => {
                                  try {
                                    setSubmitLoading(true);
                                    setError("");
                                    await petsAPI.requestAdoption({
                                      pet_id: pet.id,
                                      reason: "I would like to adopt this pet",
                                    });
                                    setSuccessMessage(
                                      "Adoption request submitted! Admin will review your request."
                                    );
                                    await loadData();
                                    setTimeout(
                                      () => setSuccessMessage(""),
                                      3000
                                    );
                                  } catch (err) {
                                    setError(
                                      err.response?.data?.error ||
                                        "Failed to submit adoption request. Please try again."
                                    );
                                  } finally {
                                    setSubmitLoading(false);
                                  }
                                }}
                                disabled={submitLoading}
                                className="w-full px-4 py-3 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 flex items-center justify-center gap-2"
                              >
                                <span className="text-lg">🐾</span>
                                Request Adoption
                              </button>
                            )}
                          </div>
                          <button
                            onClick={() => fetchPetDetails(pet.id)}
                            className="mt-3 w-full px-4 py-3 bg-gradient-to-r from-purple-500 via-purple-600 to-purple-700 text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 flex items-center justify-center gap-2"
                          >
                            <span className="text-lg">👁️</span>
                            View Full Details
                          </button>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="col-span-full text-center py-16">
                      <div className="text-6xl mb-4">🐾</div>
                      <p className="text-gray-500 text-lg">
                        No pets available for adoption at the moment
                      </p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === "post-pet-adoption" && (
              <div className="bg-gradient-to-br from-white to-purple-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                  <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    ➕
                  </span>
                  <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    POST YOUR PET FOR ADOPTION
                  </span>
                </h2>
                <form onSubmit={handlePostPetForAdoption}>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Pet Name *
                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.name}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            name: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter pet name"
                      />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Pet Type *
                      </label>
                      <select
                        value={postAdoptionForm.type}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            type: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors bg-slate-50/50"
                      >
                        <option value="">Select Type</option>
                        <option value="Dog">Dog</option>
                        <option value="Cat">Cat</option>
                        <option value="Bird">Bird</option>
                        <option value="Rabbit">Rabbit</option>
                        <option value="Other">Other</option>
                      </select>
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Breed
                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.breed}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            breed: e.target.value,
                          })
                        }
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Enter breed"
                      />
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Age (years) *
                      </label>
                      <input
                        type="number"
                        min="0"
                        value={postAdoptionForm.age}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            age: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Age in years"
                      />
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Gender *
                      </label>
                      <select
                        value={postAdoptionForm.gender}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            gender: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors bg-slate-50/50"
                      >
                        <option value="">Select Gender</option>
                        <option value="Male">Male</option>
                        <option value="Female">Female</option>
                      </select>
                    </div>
                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Location *
                      </label>
                      <input
                        type="text"
                        value={postAdoptionForm.location}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            location: e.target.value,
                          })
                        }
                        required
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                        placeholder="Current location"
                      />
                    </div>
                  </div>

                  <div className="flex flex-col mb-6">
                    <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                      Description
                    </label>
                    <textarea
                      rows="4"
                      value={postAdoptionForm.description}
                      onChange={(e) =>
                        setPostAdoptionForm({
                          ...postAdoptionForm,
                          description: e.target.value,
                        })
                      }
                      className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors resize-none"
                      placeholder="Describe your pet's temperament, habits, and why they're great for adoption..."
                    />
                  </div>

                  <div className="flex flex-col mb-6">
                    <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                      Pet Image
                    </label>
                    <input
                      type="file"
                      accept="image/*"
                      onChange={(e) =>
                        setPostAdoptionForm({
                          ...postAdoptionForm,
                          image: e.target.files[0],
                        })
                      }
                      className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                    />
                  </div>

                  <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4 flex items-center gap-2">
                    <span className="text-2xl">💊</span>
                    Medical Information
                  </h3>

                  <div className="space-y-4 mb-6">
                    <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-slate-700 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-600 transition-colors">
                      <input
                        type="checkbox"
                        checked={postAdoptionForm.is_vaccinated}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            is_vaccinated: e.target.checked,
                          })
                        }
                        className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                      />
                      <label className="text-sm font-medium text-gray-700 dark:text-white cursor-pointer select-none">
                        Is Vaccinated
                      </label>
                    </div>

                    {postAdoptionForm.is_vaccinated && (
                      <div className="ml-8 space-y-4 animate-fadeIn">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div className="flex flex-col">
                            <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                              Vaccination Date
                            </label>
                            <input
                              type="date"
                              value={postAdoptionForm.vaccination_date}
                              onChange={(e) =>
                                setPostAdoptionForm({
                                  ...postAdoptionForm,
                                  vaccination_date: e.target.value,
                                })
                              }
                              className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                            />
                          </div>
                          <div className="flex flex-col">
                            <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                              Vaccination Type
                            </label>
                            <input
                              type="text"
                              value={postAdoptionForm.vaccination_type}
                              onChange={(e) =>
                                setPostAdoptionForm({
                                  ...postAdoptionForm,
                                  vaccination_type: e.target.value,
                                })
                              }
                              className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                              placeholder="e.g., Rabies, DHPP"
                            />
                          </div>
                        </div>
                        <div className="flex flex-col">
                          <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                            Vaccination Certificate
                          </label>
                          <input
                            type="file"
                            accept=".pdf,.jpg,.jpeg,.png"
                            onChange={(e) =>
                              setPostAdoptionForm({
                                ...postAdoptionForm,
                                vaccination_certificate: e.target.files[0],
                              })
                            }
                            className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                          />
                          <p className="text-xs text-gray-500 dark:text-slate-300 mt-2">
                            Upload PDF or image file
                          </p>
                        </div>
                      </div>
                    )}

                    <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-slate-700 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-600 transition-colors">
                      <input
                        type="checkbox"
                        checked={postAdoptionForm.is_diseased}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            is_diseased: e.target.checked,
                          })
                        }
                        className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                      />
                      <label className="text-sm font-medium text-gray-700 dark:text-white cursor-pointer select-none">
                        Has Health Conditions
                      </label>
                    </div>

                    {postAdoptionForm.is_diseased && (
                      <div className="ml-8 flex flex-col animate-fadeIn">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Health Condition Description
                        </label>
                        <textarea
                          rows="3"
                          value={postAdoptionForm.disease_description}
                          onChange={(e) =>
                            setPostAdoptionForm({
                              ...postAdoptionForm,
                              disease_description: e.target.value,
                            })
                          }
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors resize-none"
                          placeholder="Describe any health conditions or special care needs..."
                        />
                      </div>
                    )}
                  </div>

                  <button
                    type="submit"
                    disabled={submitLoading}
                    className="w-full px-6 py-4 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 disabled:hover:shadow-none"
                  >
                    {submitLoading ? (
                      <span className="flex items-center justify-center gap-2">
                        <svg
                          className="animate-spin h-5 w-5"
                          viewBox="0 0 24 24"
                        >
                          <circle
                            className="opacity-25"
                            cx="12"
                            cy="12"
                            r="10"
                            stroke="currentColor"
                            strokeWidth="4"
                            fill="none"
                          />
                          <path
                            className="opacity-75"
                            fill="currentColor"
                            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                          />
                        </svg>
                        Posting...
                      </span>
                    ) : (
                      "Post Pet for Adoption"
                    )}
                  </button>
                </form>
              </div>
            )}

            {activeTab === "my-adoption-posts" && (
              <div className="my-adoption-posts-section">
                <div className="section-header">
                  <span className="material-icons">article</span>
                  MY ADOPTION POSTS ({myAdoptionPosts.length})
                </div>
                <div className="reports-grid">
                  {loading ? (
                    <div className="loading">
                      Loading your adoption posts...
                    </div>
                  ) : myAdoptionPosts.length > 0 ? (
                    myAdoptionPosts.map((post) => (
                      <div
                        key={post.id}
                        className="dashboard-pet-card my-adoption-post"
                      >
                        <div className="pet-card-image">
                          <img
                            src={getImageUrl(post.image)}
                            alt={post.name}
                            onError={(e) => {
                              e.target.src = "/default-pet.png";
                            }}
                          />
                          <div className="pet-name-overlay">
                            <h3>{post.name}</h3>
                          </div>
                        </div>
                        <div className="pet-card-info">
                          <div className="pet-type">{post.type}</div>
                          <div className="pet-details">
                            {post.breed && (
                              <span className="pet-breed">{post.breed}</span>
                            )}
                            <span className="pet-age">
                              🎂 {post.age} years old
                            </span>
                            <span className="pet-gender">
                              {post.gender === "Male" ? "♂️" : "♀️"}{" "}
                              {post.gender}
                            </span>
                            {post.location && (
                              <span className="pet-location">
                                📍 {post.location}
                              </span>
                            )}
                          </div>
                          <div className="pet-description">
                            {post.description
                              ? post.description.length > 100
                                ? `${post.description.substring(0, 100)}...`
                                : post.description
                              : "No description available"}
                          </div>
                          <div className="pet-medical-info">
                            {post.is_vaccinated && (
                              <span className="badge vaccinated">
                                ✓ Vaccinated
                              </span>
                            )}
                            {post.is_diseased && (
                              <span className="badge health-issue">
                                ⚠ Health Condition
                              </span>
                            )}
                          </div>
                          <div
                            className={`pet-status-badge status-${post.report_status}`}
                          >
                            {post.report_status === "pending" &&
                              "⏳ PENDING ADMIN REVIEW"}
                            {post.report_status === "accepted" &&
                              "✅ APPROVED - LIVE"}
                            {post.report_status === "rejected" && "❌ REJECTED"}
                          </div>
                          {post.admin_comment && (
                            <div className="admin-comment">
                              <strong>Admin Comment:</strong>{" "}
                              {post.admin_comment}
                            </div>
                          )}
                          <div className="post-date">
                            Posted:{" "}
                            {new Date(post.created_at).toLocaleDateString()}
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="no-reports">
                      <span className="material-icons">article</span>
                      <p>You haven't posted any pets for adoption yet</p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === "profile" && (
              <div className="bg-gradient-to-br from-white to-purple-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                <div className="flex items-center gap-3 mb-6">
                  <span className="material-icons text-3xl text-primary-blue">
                    person
                  </span>
                  <h2 className="text-2xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    PROFILE MANAGEMENT
                  </h2>
                </div>

                <div className="grid md:grid-cols-3 gap-8">
                  {/* Profile Image Section */}
                  <div className="md:col-span-1 flex flex-col items-center">
                    <div className="relative w-48 h-48 mb-6">
                      {profileImagePreview ? (
                        <img
                          src={profileImagePreview}
                          alt="Profile"
                          className="w-full h-full rounded-full object-cover border-4 border-primary-blue shadow-xl"
                        />
                      ) : (
                        <div className="w-full h-full rounded-full bg-gradient-to-br from-blue-100 to-teal-100 flex items-center justify-center border-4 border-primary-blue shadow-xl">
                          <span className="material-icons text-6xl text-primary-blue">
                            person
                          </span>
                        </div>
                      )}
                    </div>

                    {isEditingProfile && (
                      <div className="w-full">
                        <label
                          htmlFor="profile-image-input"
                          className="flex items-center justify-center gap-2 px-4 py-3 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-xl cursor-pointer hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                        >
                          <span className="material-icons">photo_camera</span>
                          <span className="font-semibold">Change Photo</span>
                        </label>
                        <input
                          id="profile-image-input"
                          type="file"
                          accept="image/*"
                          onChange={handleProfileImageChange}
                          className="hidden"
                        />
                      </div>
                    )}
                  </div>

                  {/* Profile Details Section */}
                  <div className="md:col-span-2">
                    <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl p-6 shadow-lg border border-blue-100 dark:border-slate-600 mb-6">
                      <div className="flex items-start justify-between mb-6">
                        <div>
                          <h3 className="text-2xl font-bold text-gray-800 dark:text-white">
                            {profileData.first_name}{" "}
                            {profileData.last_name || user?.username}
                          </h3>
                          <p className="text-gray-500 dark:text-slate-300 mt-1">
                            {profileData.email}
                          </p>
                        </div>

                        {!isEditingProfile ? (
                          <button
                            className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                            onClick={() => setIsEditingProfile(true)}
                          >
                            <span className="material-icons text-sm">edit</span>
                            <span className="font-semibold">Edit Profile</span>
                          </button>
                        ) : (
                          <div className="flex gap-2">
                            <button
                              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-green-500 to-green-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                              onClick={handleProfileSubmit}
                              disabled={submitLoading}
                            >
                              <span className="material-icons text-sm">
                                save
                              </span>
                              <span className="font-semibold">
                                {submitLoading ? "Saving..." : "Save"}
                              </span>
                            </button>
                            <button
                              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-red-500 to-red-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                              onClick={() => {
                                setIsEditingProfile(false);
                                setProfileImage(null);
                                setProfileImagePreview(
                                  getImageUrl(profileData.profile_picture)
                                );
                              }}
                            >
                              <span className="material-icons text-sm">
                                cancel
                              </span>
                              <span className="font-semibold">Cancel</span>
                            </button>
                          </div>
                        )}
                      </div>

                      {isEditingProfile ? (
                        <form
                          onSubmit={handleProfileSubmit}
                          className="space-y-4"
                        >
                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                First Name
                              </label>
                              <input
                                type="text"
                                name="first_name"
                                value={profileData.first_name}
                                onChange={handleProfileInputChange}
                                placeholder="Enter first name"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                Last Name
                              </label>
                              <input
                                type="text"
                                name="last_name"
                                value={profileData.last_name}
                                onChange={handleProfileInputChange}
                                placeholder="Enter last name"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                              />
                            </div>
                          </div>

                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                Email
                              </label>
                              <input
                                type="email"
                                name="email"
                                value={profileData.email}
                                onChange={handleProfileInputChange}
                                placeholder="Enter email address"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                Phone Number
                              </label>
                              <input
                                type="tel"
                                name="phone_no"
                                value={profileData.phone_no}
                                onChange={handleProfileInputChange}
                                placeholder="Enter phone number"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                              />
                            </div>
                          </div>

                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                City
                              </label>
                              <input
                                type="text"
                                name="city"
                                value={profileData.city}
                                onChange={handleProfileInputChange}
                                placeholder="Enter city"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                State
                              </label>
                              <input
                                type="text"
                                name="state"
                                value={profileData.state}
                                onChange={handleProfileInputChange}
                                placeholder="Enter state"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                              />
                            </div>
                          </div>

                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                PIN Code
                              </label>
                              <input
                                type="text"
                                name="pincode"
                                value={profileData.pincode}
                                onChange={handleProfileInputChange}
                                placeholder="Enter PIN code"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                Gender
                              </label>
                              <select
                                name="gender"
                                value={profileData.gender}
                                onChange={handleProfileInputChange}
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200 bg-white dark:bg-slate-700"
                              >
                                <option value="">Select Gender</option>
                                <option value="Male">Male</option>
                                <option value="Female">Female</option>
                                <option value="Other">Other</option>
                              </select>
                            </div>
                          </div>

                          <div>
                            <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                              Address
                            </label>
                            <textarea
                              name="address"
                              value={profileData.address}
                              onChange={handleProfileInputChange}
                              placeholder="Enter complete address"
                              rows="3"
                              className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200 resize-none"
                            />
                          </div>
                        </form>
                      ) : (
                        <div className="grid md:grid-cols-2 gap-4">
                          <div className="p-4 bg-gradient-to-br from-blue-50 to-blue-100 dark:from-blue-900 dark:to-blue-800 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 dark:text-slate-200 uppercase tracking-wide">
                              Phone
                            </span>
                            <p className="text-lg font-semibold text-gray-800 dark:text-white mt-1">
                              {profileData.phone_no || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-teal-50 to-teal-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 dark:text-slate-200 uppercase tracking-wide">
                              City
                            </span>
                            <p className="text-lg font-semibold text-gray-800 dark:text-white mt-1">
                              {profileData.city || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-purple-50 to-purple-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 dark:text-slate-200 uppercase tracking-wide">
                              State
                            </span>
                            <p className="text-lg font-semibold text-gray-800 dark:text-white mt-1">
                              {profileData.state || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-pink-50 to-pink-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 dark:text-slate-200 uppercase tracking-wide">
                              PIN Code
                            </span>
                            <p className="text-lg font-semibold text-gray-800 dark:text-white mt-1">
                              {profileData.pincode || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-yellow-50 to-yellow-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 dark:text-slate-200 uppercase tracking-wide">
                              Gender
                            </span>
                            <p className="text-lg font-semibold text-gray-800 dark:text-white mt-1">
                              {profileData.gender || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-indigo-50 to-indigo-100 rounded-xl md:col-span-2">
                            <span className="text-xs font-bold text-gray-600 dark:text-slate-200 uppercase tracking-wide">
                              Address
                            </span>
                            <p className="text-lg font-semibold text-gray-800 dark:text-white mt-1">
                              {profileData.address || "Not provided"}
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </main>
        </div>
      </div>

      {/* Pet Detail Modal */}
      {showDetailModal && (
        <div
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn"
          onClick={closeDetailModal}
        >
          <div
            className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-800 dark:to-slate-700 rounded-3xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto relative animate-slideUp border dark:border-slate-600"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Close Button */}
            <button
              onClick={closeDetailModal}
              className="absolute top-4 right-4 z-10 bg-white/90 dark:bg-slate-700/90 hover:bg-red-500 text-gray-600 dark:text-white hover:text-white rounded-full p-2 shadow-lg transition-all duration-300 transform hover:scale-110"
            >
              <span className="material-icons">close</span>
            </button>

            {detailLoading ? (
              <div className="flex items-center justify-center py-20">
                <div className="text-center">
                  <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary-blue mb-4"></div>
                  <p className="text-gray-600 dark:text-white">Loading pet details...</p>
                </div>
              </div>
            ) : selectedPetDetails ? (
              <div className="p-8">
                {/* Header Section with Image */}
                <div className="flex flex-col md:flex-row gap-6 mb-6">
                  {/* Pet Image */}
                  <div className="md:w-1/2">
                    <div className="relative rounded-2xl overflow-hidden shadow-xl">
                      <img
                        src={getImageUrl(selectedPetDetails.pet_info.image)}
                        alt={selectedPetDetails.pet_info.name}
                        className="w-full h-96 object-cover"
                        onError={(e) => {
                          e.target.src = "/default-pet.png";
                        }}
                      />
                      <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                        <h2 className="text-3xl font-bold text-white">
                          {selectedPetDetails.pet_info.name}
                        </h2>
                      </div>
                    </div>
                  </div>

                  {/* Quick Info */}
                  <div className="md:w-1/2 space-y-4">
                    <div className="inline-block px-4 py-2 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-full text-sm font-semibold shadow-lg">
                      {selectedPetDetails.pet_info.type}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div className="bg-gradient-to-br from-blue-50 to-blue-100 dark:from-blue-900 dark:to-blue-800 p-4 rounded-xl">
                        <span className="text-xs text-gray-600 dark:text-slate-200 font-semibold">
                          BREED
                        </span>
                        <p className="text-lg font-bold text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.breed || "Unknown"}
                        </p>
                      </div>
                      <div className="bg-gradient-to-br from-teal-50 to-teal-100 dark:from-teal-900 dark:to-teal-800 p-4 rounded-xl">
                        <span className="text-xs text-gray-600 dark:text-slate-200 font-semibold">
                          AGE
                        </span>
                        <p className="text-lg font-bold text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.age || "Unknown"} years
                        </p>
                      </div>
                      <div className="bg-gradient-to-br from-purple-50 to-purple-100 dark:from-purple-900 dark:to-purple-800 p-4 rounded-xl">
                        <span className="text-xs text-gray-600 dark:text-slate-200 font-semibold">
                          GENDER
                        </span>
                        <p className="text-lg font-bold text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.gender || "Unknown"}
                        </p>
                      </div>
                      <div className="bg-gradient-to-br from-pink-50 to-pink-100 dark:from-pink-900 dark:to-pink-800 p-4 rounded-xl">
                        <span className="text-xs text-gray-600 dark:text-slate-200 font-semibold">
                          COLOR
                        </span>
                        <p className="text-lg font-bold text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.colour || "Unknown"}
                        </p>
                      </div>
                    </div>

                    <div
                      className={`px-4 py-3 rounded-xl text-center font-semibold ${
                        selectedPetDetails.pet_info.status === "available"
                          ? "bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100"
                          : selectedPetDetails.pet_info.status === "adopted"
                          ? "bg-blue-100 text-blue-700 dark:bg-blue-800 dark:text-blue-100"
                          : "bg-gray-100 text-gray-700 dark:text-white"
                      }`}
                    >
                      {selectedPetDetails.pet_info.status?.toUpperCase()}
                    </div>
                  </div>
                </div>

                {/* Description */}
                <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 p-6 rounded-2xl border border-blue-100 dark:border-slate-600">
                  <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                    <span className="material-icons text-primary-blue">
                      description
                    </span>
                    Description
                  </h3>
                  <p className="text-gray-700 dark:text-white leading-relaxed">
                    {selectedPetDetails.pet_info.description ||
                      "No description available"}
                  </p>
                </div>

                {/* Location Info */}
                <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 p-6 rounded-2xl border border-blue-100 dark:border-slate-600">
                  <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                    <span className="material-icons text-primary-teal">
                      location_on
                    </span>
                    Location Details
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                      <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                        Location
                      </span>
                      <p className="text-gray-800 dark:text-white">
                        {selectedPetDetails.pet_info.location ||
                          "Not specified"}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                        City
                      </span>
                      <p className="text-gray-800 dark:text-white">
                        {selectedPetDetails.pet_info.city || "Not specified"}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                        State
                      </span>
                      <p className="text-gray-800 dark:text-white">
                        {selectedPetDetails.pet_info.state || "Not specified"}
                      </p>
                    </div>
                  </div>
                </div>

                {/* Medical History */}
                {selectedPetDetails.medical_history && (
                  <div className="mb-6 bg-gradient-to-br from-green-50 to-green-100 dark:from-green-900 dark:to-green-800 p-6 rounded-2xl border border-green-200 dark:border-green-700">
                    <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                      <span className="material-icons text-green-600 dark:text-green-400">
                        medical_services
                      </span>
                      Medical History
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl">
                        <span className="text-sm text-gray-600 dark:text-white font-semibold">
                          Vaccination Status
                        </span>
                        <p className="text-gray-800 dark:text-white flex items-center gap-2 mt-1">
                          {selectedPetDetails.pet_info.is_vaccinated ? (
                            <>
                              <span className="material-icons text-green-600 dark:text-green-400">
                                check_circle
                              </span>
                              Vaccinated
                            </>
                          ) : (
                            <>
                              <span className="material-icons text-red-600 dark:text-red-400">
                                cancel
                              </span>
                              Not Vaccinated
                            </>
                          )}
                        </p>
                      </div>
                      <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl">
                        <span className="text-sm text-gray-600 dark:text-white font-semibold">
                          Health Status
                        </span>
                        <p className="text-gray-800 dark:text-white flex items-center gap-2 mt-1">
                          {selectedPetDetails.pet_info.is_diseased ? (
                            <>
                              <span className="material-icons text-orange-600 dark:text-orange-400">
                                warning
                              </span>
                              Has Health Condition
                            </>
                          ) : (
                            <>
                              <span className="material-icons text-green-600 dark:text-green-400">
                                check_circle
                              </span>
                              Healthy
                            </>
                          )}
                        </p>
                      </div>
                      {selectedPetDetails.medical_history.vaccine_name && (
                        <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl">
                          <span className="text-sm text-gray-600 dark:text-white font-semibold">
                            Vaccine Name
                          </span>
                          <p className="text-gray-800 dark:text-white mt-1">
                            {selectedPetDetails.medical_history.vaccine_name}
                          </p>
                        </div>
                      )}
                      {selectedPetDetails.medical_history
                        .last_vaccinated_date && (
                        <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl">
                          <span className="text-sm text-gray-600 dark:text-white font-semibold">
                            Last Vaccinated
                          </span>
                          <p className="text-gray-800 dark:text-white mt-1">
                            {new Date(
                              selectedPetDetails.medical_history.last_vaccinated_date
                            ).toLocaleDateString()}
                          </p>
                        </div>
                      )}
                      {selectedPetDetails.medical_history.disease_name && (
                        <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl col-span-2">
                          <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                            Disease/Condition
                          </span>
                          <p className="text-gray-800 dark:text-white mt-1">
                            {selectedPetDetails.medical_history.disease_name}
                          </p>
                          {selectedPetDetails.medical_history.stage && (
                            <p className="text-sm text-gray-600 dark:text-slate-200 mt-1">
                              Stage: {selectedPetDetails.medical_history.stage}
                            </p>
                          )}
                        </div>
                      )}
                      {selectedPetDetails.medical_history.treatment_name && (
                        <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl col-span-2">
                          <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                            Treatment
                          </span>
                          <p className="text-gray-800 dark:text-white mt-1">
                            {selectedPetDetails.medical_history.treatment_name}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {/* Physical Details */}
                <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 p-6 rounded-2xl border border-blue-100 dark:border-slate-600">
                  <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                    <span className="material-icons text-primary-blue">
                      info
                    </span>
                    Physical Details
                  </h3>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div>
                      <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                        Weight
                      </span>
                      <p className="text-gray-800 dark:text-white">
                        {selectedPetDetails.pet_info.weight
                          ? `${selectedPetDetails.pet_info.weight} kg`
                          : "Not specified"}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                        Color
                      </span>
                      <p className="text-gray-800 dark:text-white">
                        {selectedPetDetails.pet_info.colour || "Not specified"}
                      </p>
                    </div>
                    <div className="col-span-2">
                      <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                        Created
                      </span>
                      <p className="text-gray-800 dark:text-white">
                        {new Date(
                          selectedPetDetails.pet_info.created_at
                        ).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                </div>

                {/* Reports Section */}
                {selectedPetDetails.reports &&
                  selectedPetDetails.reports.length > 0 && (
                    <div className="mb-6 bg-gradient-to-br from-yellow-50 to-yellow-100 dark:from-yellow-900 dark:to-yellow-800 p-6 rounded-2xl border border-yellow-200 dark:border-yellow-700">
                      <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                        <span className="material-icons text-yellow-600 dark:text-yellow-400">
                          report
                        </span>
                        Reports ({selectedPetDetails.total_reports})
                      </h3>
                      <div className="space-y-3">
                        {selectedPetDetails.reports
                          .slice(0, 3)
                          .map((report) => (
                            <div
                              key={report.id}
                              className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl"
                            >
                              <div className="flex items-center justify-between mb-2">
                                <span className="font-semibold text-gray-800 dark:text-white">
                                  {report.user_name}
                                </span>
                                <span
                                  className={`px-3 py-1 rounded-full text-xs font-semibold ${
                                    report.report_status === "accepted"
                                      ? "bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100"
                                      : report.report_status === "pending"
                                      ? "bg-yellow-100 text-yellow-700 dark:bg-yellow-800 dark:text-yellow-100"
                                      : "bg-red-100 text-red-700 dark:bg-red-800 dark:text-red-100"
                                  }`}
                                >
                                  {report.report_status}
                                </span>
                              </div>
                              <p className="text-sm text-gray-600 dark:text-slate-200">
                                {report.description}
                              </p>
                              <span className="text-xs text-gray-500 dark:text-slate-300 mt-2 block">
                                {new Date(
                                  report.created_at
                                ).toLocaleDateString()}
                              </span>
                            </div>
                          ))}
                      </div>
                    </div>
                  )}

                {/* Action Buttons */}
                <div className="flex gap-4 mt-6">
                  <button
                    onClick={closeDetailModal}
                    className="flex-1 px-6 py-3 bg-gradient-to-r from-gray-500 to-gray-600 text-white font-semibold rounded-xl hover:shadow-xl transform hover:scale-105 transition-all duration-300"
                  >
                    Close
                  </button>
                  {selectedPetDetails.pet_info.status === "available" && (
                    <button
                      className="flex-1 px-6 py-3 bg-gradient-to-r from-primary-blue to-primary-teal text-white font-semibold rounded-xl hover:shadow-xl transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                      onClick={() => {
                        closeDetailModal();
                        setActiveTab("adopt-pet");
                      }}
                    >
                      <span className="material-icons">favorite</span>
                      Adopt This Pet
                    </button>
                  )}
                </div>
              </div>
            ) : (
              <div className="flex items-center justify-center py-20">
                <p className="text-gray-600 dark:text-white">No details available</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Notification Detail Modal */}
      {showNotificationModal && selectedNotification && (
        <div
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn"
          onClick={() => setShowNotificationModal(false)}
        >
          <div
            className="bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-hidden border-2 border-blue-200 dark:border-slate-600 animate-slideUp"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Modal Header */}
            <div className="bg-gradient-to-r from-primary-blue to-primary-teal p-6 border-b border-blue-200 dark:border-slate-600">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <span className="material-icons text-white text-3xl">
                    notifications_active
                  </span>
                  <h2 className="text-2xl font-bold text-white">
                    Notification Details
                  </h2>
                </div>
                <button
                  onClick={() => setShowNotificationModal(false)}
                  className="p-2 hover:bg-white/20 rounded-full transition-colors"
                >
                  <span className="material-icons text-white">close</span>
                </button>
              </div>
            </div>

            {/* Modal Content */}
            <div className="p-6 overflow-y-auto max-h-[calc(90vh-120px)]">
              <div className="space-y-6">
                {/* Notification Status */}
                <div className="flex items-center gap-2">
                  <span
                    className={`px-4 py-2 rounded-full text-sm font-semibold ${
                      selectedNotification.is_read
                        ? "bg-gray-200 text-gray-700 dark:text-white"
                        : "bg-blue-500 text-white"
                    }`}
                  >
                    {selectedNotification.is_read ? "Read" : "Unread"}
                  </span>
                  <span className="text-sm text-gray-500 dark:text-slate-300">
                    {new Date(selectedNotification.created_at).toLocaleString()}
                  </span>
                </div>

                {/* Notification Title (if exists) */}
                {selectedNotification.title && (
                  <div className="bg-gradient-to-br from-white to-blue-50 rounded-xl p-4 border border-blue-200 shadow-sm">
                    <h3 className="text-xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
                      <span className="material-icons text-primary-blue">
                        title
                      </span>
                      {selectedNotification.title}
                    </h3>
                  </div>
                )}

                {/* Notification Message */}
                <div className="bg-gradient-to-br from-white to-blue-50 rounded-xl p-6 border border-blue-200 shadow-sm">
                  <h4 className="text-sm font-semibold text-gray-600 dark:text-slate-200 uppercase tracking-wide mb-3 flex items-center gap-2">
                    <span className="material-icons text-primary-blue text-sm">
                      message
                    </span>
                    Message
                  </h4>
                  <p className="text-gray-800 dark:text-white text-lg leading-relaxed whitespace-pre-wrap">
                    {selectedNotification.message}
                  </p>
                </div>

                {/* Additional Info (if exists) */}
                {selectedNotification.notification_type && (
                  <div className="bg-gradient-to-br from-blue-50 to-teal-50 rounded-xl p-4 border border-blue-200">
                    <div className="flex items-center gap-2">
                      <span className="material-icons text-primary-blue">
                        info
                      </span>
                      <span className="text-sm font-semibold text-gray-700 dark:text-white">
                        Type:
                      </span>
                      <span className="text-sm text-gray-600 dark:text-slate-200">
                        {selectedNotification.notification_type}
                      </span>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Modal Footer */}
            <div className="bg-slate-100 p-4 border-t border-blue-200 flex justify-end gap-3">
              <button
                onClick={() => setShowNotificationModal(false)}
                className="px-6 py-2 bg-gradient-to-r from-primary-blue to-primary-teal text-white font-semibold rounded-xl hover:shadow-lg transition-all duration-200 flex items-center gap-2"
              >
                <span className="material-icons text-sm">check</span>
                Close
              </button>
            </div>
          </div>
        </div>
      )}
      </div>
    </div>
  );
};

export default UserDashboard;
